<script lang="ts">
  import type { Snippet } from 'svelte';
  import type { CalculationView } from '../types';
  import { date, duration, euro, number, percent, relativeUpdatedAt, updatedAt } from '../services/formatters';
  import { cpiPointForDate } from '../../backtest.mjs';
  import LineChart from './LineChart.svelte';
  let { comparisonView, accountLabel = 'Account', accountMwrDescription = 'Your annualized account outcome from the same external cash flows, credited interest, and entered accrued base interest.', portfolioChartLabel = 'your account', portfolioChartAriaLabel, timeWeightedChartLabel = 'your account', chartAccountLabel = 'Your account', initialReturnChartMode = 'time-weighted', beforeLedger }: { comparisonView?: CalculationView; accountLabel?: string; accountMwrDescription?: string; portfolioChartLabel?: string; portfolioChartAriaLabel?: string; timeWeightedChartLabel?: string; chartAccountLabel?: string; initialReturnChartMode?: 'portfolio-value' | 'time-weighted'; beforeLedger?: Snippet } = $props();
  const currentAccount = () => accountLabel === 'Account';
  const initialChartMode = () => initialReturnChartMode;
  let returnChartMode = $state<'portfolio-value' | 'time-weighted'>(initialChartMode());
  const isSecondaryReturn = (value: number | undefined, other: number | undefined) => {
    if (value === undefined || other === undefined || value === other) return false;
    return (value > 0 && other > 0 && value < other) || (value < 0 && other < 0 && value > other);
  };
  let view = $derived(comparisonView);
  let result = $derived(comparisonView?.result);
  let settings = $derived(comparisonView?.settings);
  let negative = $derived((result?.missedAmount ?? 0) < -0.005);
  let valuesAreEqual = $derived(Math.abs(result?.missedAmount ?? 0) < 0.005);
  let returnDifference = $derived(result?.csh2MoneyWeightedReturn !== undefined && result.accountMoneyWeightedReturn !== undefined ? result.csh2MoneyWeightedReturn - result.accountMoneyWeightedReturn : undefined);
  let csh2UpdatedAt = $derived(view ? new Date(view.metadata.cachedAt) : new Date(0));
  let estrUpdatedAt = $derived(view?.rateMetadata.cachedAt ? new Date(view.rateMetadata.cachedAt) : undefined);
  let cpiUpdatedAt = $derived(view ? new Date(view.cpiMetadata.cachedAt) : new Date(0));
  let latestCpiMonth = $derived(view ? Object.keys(view.cpiMetadata.indices).sort().at(-1) : undefined);
  let valuationCpi = $derived(view ? cpiPointForDate(view.cpiMetadata.indices, view.to) : undefined);
  let portfolioProjection = $derived(view?.returnSeries.portfolioValue.projected);
  let timeWeightedProjection = $derived(view?.returnSeries.timeWeighted.projected);
</script>
<section class="comparison-results" aria-live="polite">
  {#if view && result && settings}
  <div class="result-heading"><div><p class="eyebrow">As of {result.valuation.date}</p><h2>Backtest result</h2></div><p class="source">CSH2 data last updated <time class="timestamp" datetime={view.metadata.cachedAt} title={updatedAt.format(csh2UpdatedAt)} data-tooltip={updatedAt.format(csh2UpdatedAt)}>{relativeUpdatedAt(csh2UpdatedAt)}</time><br />{#if estrUpdatedAt}€STR rate last updated <time class="timestamp" datetime={view.rateMetadata.cachedAt} title={updatedAt.format(estrUpdatedAt)} data-tooltip={updatedAt.format(estrUpdatedAt)}>{relativeUpdatedAt(estrUpdatedAt)}</time> (source: ECB statistics){:else}€STR rate last update unavailable (source: ECB statistics){/if}<br />Belgian CPI last updated <time class="timestamp" datetime={view.cpiMetadata.cachedAt} title={updatedAt.format(cpiUpdatedAt)} data-tooltip={updatedAt.format(cpiUpdatedAt)}>{relativeUpdatedAt(cpiUpdatedAt)}</time> (latest observed month: {latestCpiMonth}; source: Statbel)</p></div>
  {#if settings.returnMode === 'real'}<p class="real-coverage-note">Inflation-adjusted returns use Belgian CPI.{#if valuationCpi?.status === 'extrapolated'}&#32;The latest portion is provisional and extrapolated from trailing 12-month observed inflation after {valuationCpi.lowerMonth}.{/if}</p>{/if}
  <div class="metrics">
    <div class="metric-row metric-row-values outcome-returns"><article class:negative={result.csh2MoneyWeightedReturn !== undefined && result.csh2MoneyWeightedReturn < 0} class:comparison-secondary={isSecondaryReturn(result.csh2MoneyWeightedReturn, result.accountMoneyWeightedReturn)} class="metric main"><p>CSH2 annualized money-weighted return</p><strong>{result.csh2MoneyWeightedReturn === undefined ? '—' : `${percent(result.csh2MoneyWeightedReturn)}%`}</strong><small>{currentAccount() ? 'Your annualized outcome from the dated deposits and withdrawals, after transaction costs and the selected taxes.' : 'CSH2 outcome from the dated deposits and withdrawals, after transaction costs and the selected taxes.'}</small></article><article class:negative={result.accountMoneyWeightedReturn !== undefined && result.accountMoneyWeightedReturn < 0} class:comparison-secondary={isSecondaryReturn(result.accountMoneyWeightedReturn, result.csh2MoneyWeightedReturn)} class="metric main"><p>{accountLabel} annualized money-weighted return</p><strong>{result.accountMoneyWeightedReturn === undefined ? '—' : `${percent(result.accountMoneyWeightedReturn)}%`}</strong><small>{accountMwrDescription}</small></article></div>
    <article class:negative class="metric missed-result"><p>{valuesAreEqual ? `CSH2 and ${accountLabel.toLowerCase()} have the same value` : negative ? `CSH2 is behind ${currentAccount() ? 'your account balance' : accountLabel.toLowerCase()} by` : `CSH2 is ahead of ${currentAccount() ? 'your account balance' : accountLabel.toLowerCase()} by`}</p><strong>{euro.format(Math.abs(result.missedAmount))}</strong><small>{returnDifference === undefined ? 'A unique annualized money-weighted return is not available for these cash flows.' : Math.abs(returnDifference) < 0.005 ? 'The annualized money-weighted returns are effectively equal.' : `The annualized money-weighted return difference is ${percent(Math.abs(returnDifference))} percentage points in ${returnDifference >= 0 ? 'CSH2’s' : currentAccount() ? 'your account’s' : `${accountLabel.toLowerCase()}'s`} favour.`}</small>{#if negative && result.breakEvenEstimate}<small>Estimated catch-up with {currentAccount() ? 'your account' : accountLabel.toLowerCase()} in <b>{duration(result.valuation.date, result.breakEvenEstimate.date)}</b></small><small>(using the selected CSH2 rate scenario of {percent(result.breakEvenEstimate.csh2AnnualRatePercent)}%)</small>{:else if negative}<small>Catch-up with {currentAccount() ? 'your account' : accountLabel.toLowerCase()} can’t be estimated from the selected CSH2 rate scenario.</small>{/if}</article>
    <div class="metric-row metric-row-values"><article class="metric"><p>CSH2 annualized time-weighted return</p><strong>{result.csh2TimeWeightedReturn === undefined ? '—' : `${percent(result.csh2TimeWeightedReturn)}%`}</strong><small>Geometrically linked portfolio performance that removes the external cash flows themselves while retaining the transaction costs and selected taxes they trigger. The CGT exemption follows the entered portfolio’s tax history.</small></article><article class="metric"><p>{accountLabel} annualized time-weighted return</p><strong>{result.accountTimeWeightedReturn === undefined ? '—' : `${percent(result.accountTimeWeightedReturn)}%`}</strong><small>Geometrically linked interest performance, with external cash flows removed.</small></article></div>
    {#if result.observedHoldingPeriods}<div class="metric-row metric-row-values"><article class="metric"><p>CSH2 backtest first broke even after</p><strong>{result.observedHoldingPeriods.breakEven && result.observedHoldingPeriods.from ? duration(result.observedHoldingPeriods.from, result.observedHoldingPeriods.breakEven.date) : 'Not yet'}</strong><small>{result.observedHoldingPeriods.breakEven ? `First observed on ${date.format(new Date(`${result.observedHoldingPeriods.breakEven.date}T00:00:00Z`))}.` : result.observedHoldingPeriods.from ? 'The CSH2 backtest has not broken even yet.' : 'No CSH2 purchase was executed.'} Net CSH2 liquidation value versus external capital, excluding account interest; includes transaction costs and selected taxes.</small></article><article class="metric"><p>CSH2 backtest first matched €STR after</p><strong>{result.observedHoldingPeriods.matchOvernight && result.observedHoldingPeriods.from ? duration(result.observedHoldingPeriods.from, result.observedHoldingPeriods.matchOvernight.date) : 'Not yet'}</strong><small>{result.observedHoldingPeriods.matchOvernight ? `First observed on ${date.format(new Date(`${result.observedHoldingPeriods.matchOvernight.date}T00:00:00Z`))}.` : result.observedHoldingPeriods.from ? 'The CSH2 backtest has not matched €STR yet.' : 'No CSH2 purchase was executed.'} Compares the same external cash flows, excluding account interest.</small></article></div>{/if}
    <div class="metric-row metric-row-values"><article class="metric"><p>{currentAccount() ? 'Net value if sold today' : 'Net value at end date'}</p><strong>{euro.format(result.netLiquidationValue)}</strong><small>After estimated final TOB and applicable tax</small></article><article class="metric"><p>Gross CSH2 value</p><strong>{euro.format(result.grossValue)}</strong><small>{number.format(result.units)} CSH2 units{result.availableCash ? ` · ${euro.format(result.availableCash)} cash` : ''}</small></article></div>
    <div class="metric-row metric-row-details"><article class="metric"><p>Taxes already paid</p><strong>{euro.format(result.paidTob + result.paidCgt + result.paidReyndersTax)}</strong><small>TOB {euro.format(result.paidTob)} · {settings.applyReyndersTax ? `Reynders Tax ${euro.format(result.paidReyndersTax)}` : `CGT ${euro.format(result.paidCgt)}`}</small></article><article class="metric"><p>{currentAccount() ? 'Taxes if sold today' : 'Taxes if sold at end date'}</p><strong>{euro.format(result.terminalTob + result.terminalCgt + result.terminalReyndersTax)}</strong><small>TOB {euro.format(result.terminalTob)} · {settings.applyReyndersTax ? `Reynders Tax ${euro.format(result.terminalReyndersTax)}` : `CGT ${euro.format(result.terminalCgt)}`}</small></article><article class="metric"><p>Broker fees</p><strong>{euro.format(result.paidBrokerFees + result.terminalBrokerFee)}</strong><small>Paid {euro.format(result.paidBrokerFees)} · {currentAccount() ? 'if sold today' : 'if sold at end date'} {euro.format(result.terminalBrokerFee)}</small></article></div>
  </div>
  <section class="panel" aria-labelledby="return-heading"><div class="section-title"><div><p class="eyebrow">Two views, two different questions</p><h3 id="return-heading">{returnChartMode === 'portfolio-value' ? 'Euro portfolio value over time' : 'Cash-flow-neutral performance'}</h3></div><div class="return-mode-picker" role="group" aria-label="Performance chart view"><button type="button" aria-pressed={returnChartMode === 'portfolio-value'} onclick={() => returnChartMode = 'portfolio-value'}>Portfolio value</button><button type="button" aria-pressed={returnChartMode === 'time-weighted'} onclick={() => returnChartMode = 'time-weighted'}>Performance</button></div></div><p class="chart-key"><span class="chart-key-csh2">CSH2 backtest</span>{#if (returnChartMode === 'portfolio-value' ? view.returnSeries.portfolioValue.overnight.length : view.returnSeries.timeWeighted.overnight.length)}<span class="chart-key-estr">Gross €STR</span>{/if}<span class="chart-key-account">{accountLabel === 'Account' ? 'Your account' : accountLabel}</span>{#if (returnChartMode === 'portfolio-value' && portfolioProjection) || (returnChartMode === 'time-weighted' && timeWeightedProjection)}<span class="chart-key-projected">Projection</span>{/if}</p>{#if returnChartMode === 'portfolio-value'}<p class="chart-explanation">{currentAccount() ? 'Actual CSH2 net liquidation value and account balance after the same deposits and withdrawals. Values are shown in current euros and are not investment returns.' : 'Actual CSH2 net liquidation value and historical savings value after the same deposits. Values are shown in current euros and are not investment returns.'}</p>{#if portfolioProjection}<p class="chart-explanation projection-explanation">Dashed through {date.format(new Date(`${portfolioProjection.throughDate}T00:00:00Z`))}: {currentAccount() ? `assumes no further cash flows, the selected CSH2 rate scenario of ${percent(portfolioProjection.csh2AnnualRatePercent)}%, and each entered fidelity premium is paid on its earned date.` : `continues the entered deposit schedule and historical savings rates, while holding the selected CSH2 rate scenario of ${percent(portfolioProjection.csh2AnnualRatePercent)}% and the latest €STR rate constant. Acquired fidelity premiums are included from their acquisition date; once credited, they join principal and can accrue normally.`}{#if portfolioProjection.baseAnnualRatePercent !== undefined} The full account balance compounds at the entered {percent(portfolioProjection.baseAnnualRatePercent)}% annual base rate, and each paid premium joins that balance for subsequent accrual.{/if}</p>{/if}{#if view.returnSeries.portfolioValue.csh2.length || view.returnSeries.portfolioValue.account.length}<LineChart accountLabel={chartAccountLabel} data={view.returnSeries.portfolioValue} unit="euro" from={view.from} to={view.to} ariaLabel={portfolioChartAriaLabel ?? `Portfolio value in euro for CSH2 and ${portfolioChartLabel} using the same external cash flows`} />{:else}<p class="chart-empty">There isn’t enough history yet to plot portfolio values.</p>{/if}{:else}<p class="chart-explanation">{currentAccount() ? 'Geometric linking removes the deposits and withdrawals themselves from performance. CSH2 still includes the broker fees, transaction taxes, and selected gain taxes those trades trigger; the account includes entered credited and accrued interest; €STR is a gross, untaxed market benchmark.' : 'Geometric linking removes the external deposits from performance. CSH2 includes the broker fees, transaction taxes, and selected gain taxes those trades trigger; historical savings includes base interest and fidelity premiums; €STR is a gross, untaxed market benchmark.'}{#if settings.returnMode === 'real'} The chart begins only once both CPI endpoints are available.{/if}</p>{#if timeWeightedProjection}<p class="chart-explanation projection-explanation">Dashed through {date.format(new Date(`${timeWeightedProjection.throughDate}T00:00:00Z`))}: {currentAccount() ? `extends each observed TWR endpoint with no further cash flows, the selected CSH2 rate scenario of ${percent(timeWeightedProjection.csh2AnnualRatePercent)}%, the latest €STR rate of ${percent(timeWeightedProjection.overnightRatePercent)}%, and ${timeWeightedProjection.baseAnnualRatePercent !== undefined ? `the entered account base rate of ${percent(timeWeightedProjection.baseAnnualRatePercent)}%` : 'the account’s observed interest assumptions'}; future fidelity premiums are credited on their earned dates and included as internal account returns.` : `continues the entered deposit schedule and historical savings rates, with the selected CSH2 and latest €STR rates held constant. Acquired fidelity premiums are included from acquisition until credited on the next quarterly payout date, then join principal and can accrue normally.`}{#if settings.returnMode === 'real'} This forward section is provisional and inflation-adjusted using trailing 12-month observed CPI extrapolation.{/if}</p>{/if}{#if view.returnSeries.timeWeighted.csh2.length || view.returnSeries.timeWeighted.overnight.length || view.returnSeries.timeWeighted.account.length}<LineChart accountLabel={chartAccountLabel} data={view.returnSeries.timeWeighted} cpiIndices={settings.returnMode === 'real' ? view.cpiMetadata.indices : undefined} from={view.from} to={view.to} ariaLabel={`Time-weighted performance of CSH2, gross Euro overnight rates, and ${timeWeightedChartLabel}, excluding external cash flows`} />{:else}<p class="chart-empty">{currentAccount() ? 'There isn’t enough CPI-covered history yet to plot time-weighted performance.' : 'There isn’t enough history yet to plot time-weighted performance.'}</p>{/if}{/if}</section>
  {@render beforeLedger?.()}
  <section class="panel ledger"><h3>Transaction ledger</h3><div class="table-wrap"><table><thead><tr><th>Date</th><th>Type</th><th>Amount</th><th>Price used</th><th>Units</th><th>Cash remaining</th><th>Broker fee</th><th>TOB</th>{#if !settings.applyReyndersTax}<th>CGT</th>{/if}{#if settings.applyReyndersTax}<th>Reynders Tax</th>{/if}{#if settings.applyCapitalGainsExemption && !settings.applyReyndersTax}<th>Exonerated CGT</th>{/if}</tr></thead><tbody>{#each result.entries as entry}<tr><td>{entry.date}</td><td>{entry.interestPayment ? 'Interest payment' : entry.type === 'inflow' ? 'Inflow / buy' : 'Outflow / sell'}</td><td>{euro.format(entry.amount)}</td><td>{entry.price === undefined ? '—' : euro.format(entry.price)}{entry.priceKind && entry.priceKind !== 'close' ? ` (${entry.priceKind})` : ''}</td><td>{entry.interestPayment ? '—' : number.format(entry.units)}</td><td>{euro.format(entry.remainingCash)}</td><td>{euro.format(entry.brokerFee)}</td><td>{euro.format(entry.tob)}</td>{#if !settings.applyReyndersTax}<td>{entry.cgt ? euro.format(entry.cgt) : '—'}</td>{/if}{#if settings.applyReyndersTax}<td>{entry.reyndersTax ? euro.format(entry.reyndersTax) : '—'}</td>{/if}{#if settings.applyCapitalGainsExemption && !settings.applyReyndersTax}<td>{entry.exoneratedCgt ? euro.format(entry.exoneratedCgt) : '—'}</td>{/if}</tr>{/each}</tbody></table></div></section>
  {/if}
</section>
